  "outcome": "escalate",
  "rationale": "We are escalating this claim because an automated check raised a fraud flag for an inflated estimate. Section 7.3 governs this issue by stating that substantially higher claims than usual must be escalated for review. The key fact is that the claimed amount of $20,910.00 significantly exceeds the typical repair cost threshold.",
  "citations": [
    {
      "clause_id": "PREM-7.3",
      "quote": "If the amount claimed is substantially higher than the usual cost of repairing the damage described, or is not supported by the itemized estimate, the claim must be escalated for review."
    }
  ]
}
